/bin/bash -lc "python - <<'PY'
from decimal import Decimal, getcontext
from pathlib import Path
import csv
from collections import defaultdict, Counter
getcontext().prec = 28

ROOT = Path('/app')
D = ROOT/'data'
SUB = ROOT/'submissions'/'initial_plan.csv'
TOL = Decimal('0.0001')

# helpers

def Dq(x):
    return Decimal(str(x))

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

weeks = [int(r['week']) for r in read_csv(D/'weeks.csv')]
weekset = set(weeks)
stage = read_csv(D/'planning_policies.csv')[0]
reserve_mult = Dq(stage['reserve_multiplier_next_week_demand'])
material_discount = Dq(stage['material_robust_discount'])
replan_penalty = Dq(stage['replan_change_penalty_per_ton'])

products = {r['product_id']: r for r in read_csv(D/'products.csv')}
materials = {r['material_id']: r for r in read_csv(D/'materials.csv')}
plants = {r['plant_id']: r for r in read_csv(D/'plants.csv')}
dcs = {r['dc_id']: r for r in read_csv(D/'warehouses.csv')}
customers = {r['customer_id']: r for r in read_csv(D/'customers.csv')}
pp = {(r['plant_id'], r['product_id']): r for r in read_csv(D/'plant_products.csv')}
bom = {(r['product_id'], r['material_id']): Dq(r['tons_material_per_ton_product']) for r in read_csv(D/'bom.csv')}
initial_inventory = {(r['dc_id'], r['product_id']): Dq(r['initial_inventory_tons']) for r in read_csv(D/'initial_inventory.csv')}
safety = {(r['dc_id'], r['product_id']): Dq(r['safety_stock_tons']) for r in read_csv(D/'safety_stock.csv')}
demand = {(int(r['week']), r['customer_id'], r['product_id']): Dq(r['demand_tons']) for r in read_csv(D/'demand.csv')}
mat_supply = {(int(r['week']), r['plant_id'], r['material_id']): (Dq(r['regular_available_tons']), Dq(r['emergency_cap_tons'])) for r in read_csv(D/'material_supply.csv')}
plant_dc_lane = {(r['plant_id'], r['dc_id']): Dq(r['weekly_capacity_tons']) for r in read_csv(D/'plant_to_dc_lanes.csv')}
dc_cust_lane = {(r['dc_id'], r['customer_id']): Dq(r['weekly_capacity_tons']) for r in read_csv(D/'dc_to_customer_lanes.csv')}
dc_transfer_lane = {(r['from_dc'], r['to_dc']): Dq(r['weekly_capacity_tons']) for r in read_csv(D/'dc_transfer_lanes.csv')}

rows = []
with open(SUB, newline='') as f:
    reader = csv.DictReader(f)
    header = reader.fieldnames
    for i, row in enumerate(reader, start=2):
        row = dict(row)
        row['_line'] = i
        row['q'] = Dq(row['quantity'])
        row['w'] = int(row['week'])
        rows.append(row)

violations = []
family_counts = Counter()

def add(family, key, rule, observed, required, repair):
    family_counts[family] += 1
    violations.append({
        'family': family,
        'key': key,
        'rule': rule,
        'observed': observed,
        'required': required,
        'repair': repair,
    })

# schema/header
expected_header = ['variable','week','item','from','to','quantity']
if header "'!= expected_header:
    add('"'schema/nullability and key coverage', 'header', 'Exact six-column schema', header, expected_header, 'Export the CSV with the required header order.')

allowed_vars = {
    'setup','produce_regular','produce_overtime','ship_plant_dc','ship_dc_customer',
    'transfer_dc','inventory','shortage','emergency_material'
}

seen_keys = defaultdict(list)
for r in rows:
    key = (r['variable'], r['week'], r['item'], r['from'], r['to'])
    seen_keys[key].append(r['_line'])
    if r['variable'] not in allowed_vars:
        add('schema/nullability and key coverage', f\"line {r['_line']}\", 'Supported variable names only', r['variable'], sorted(allowed_vars), 'Remove or rename the unsupported variable row.')
    if r['w'] not in weekset:
        add('identifier domains', f\"line {r['_line']}\", 'Week must belong to weeks.csv', r['w'], sorted(weekset), 'Use only planning-horizon weeks.')
    if r['q'] < 0:
        add('schema/nullability and key coverage', f\"line {r['_line']}\", 'Quantities must be nonnegative', str(r['q']), '>= 0', 'Replace the row with a nonnegative quantity or omit it if zero.')
    if r['q'] == 0:
        add('schema/nullability and key coverage', f\"line {r['_line']}\", 'Zero-valued rows must be omitted', str(r['q']), '> 0 for exported rows', 'Drop zero-valued rows from the export.')

for key, lines in seen_keys.items():
    if len(lines) > 1:
        add('schema/nullability and key coverage', str(key), 'Each decision key should appear at most once in the export', lines, 'unique key', 'Aggregate duplicate rows before exporting.')

product_ids = set(products)
material_ids = set(materials)
plant_ids = set(plants)
dc_ids = set(dcs)
customer_ids = set(customers)

# variable-specific domain checks
for r in rows:
    var, item, src, dst, q = r['variable'], r['item'], r['from'], r['to'], r['q']
    line = f\"line {r['_line']}\"
    if var == 'setup':
        if item not in product_ids or src not in plant_ids or dst "'!= '"'':
            add('identifier domains', line, 'setup uses item=product, from=plant, blank to', (item, src, dst), '(product, plant, blank)', 'Correct the identifiers for the setup row.')
        if q "'!= 1:
            add('"'schema/nullability and key coverage', line, 'Exported setup rows must carry quantity 1', str(q), '1', 'Use quantity 1 for active setups and omit inactive setups.')
    elif var in {'produce_regular', 'produce_overtime'}:
        if item not in product_ids or src not in plant_ids or dst "'!= '"'':
            add('identifier domains', line, f'{var} uses item=product, from=plant, blank to', (item, src, dst), '(product, plant, blank)', 'Correct the identifiers for the production row.')
    elif var == 'ship_plant_dc':
        if item not in product_ids or src not in plant_ids or dst not in dc_ids:
            add('identifier domains', line, 'ship_plant_dc uses item=product, from=plant, to=dc', (item, src, dst), '(product, plant, dc)', 'Correct the shipment endpoints.')
    elif var == 'ship_dc_customer':
        if item not in product_ids or src not in dc_ids or dst not in customer_ids:
            add('identifier domains', line, 'ship_dc_customer uses item=product, from=dc, to=customer', (item, src, dst), '(product, dc, customer)', 'Correct the shipment endpoints.')
    elif var == 'transfer_dc':
        if item not in product_ids or src not in dc_ids or dst not in dc_ids or src == dst:
            add('identifier domains', line, 'transfer_dc uses item=product, from=origin_dc, to=destination_dc, with distinct endpoints', (item, src, dst), '(product, dc, different dc)', 'Correct or remove the transfer row.')
    elif var == 'inventory':
        if item not in product_ids or src not in dc_ids or dst "'!= '"'':
            add('identifier domains', line, 'inventory uses item=product, from=dc, blank to', (item, src, dst), '(product, dc, blank)', 'Correct the inventory row identifiers.')
    elif var == 'shortage':
        if item not in product_ids or src not in customer_ids or dst "'!= '"'':
            add('identifier domains', line, 'shortage uses item=product, from=customer, blank to', (item, src, dst), '(product, customer, blank)', 'Correct the shortage row identifiers.')
    elif var == 'emergency_material':
        if item not in material_ids or src "'!= '"'external' or dst not in plant_ids:
            add('identifier domains', line, 'emergency_material uses item=material, from=external, to=plant', (item, src, dst), '(material, external, plant)', 'Correct the emergency material row identifiers.')

# aggregate rows
qty = defaultdict(Decimal)
for r in rows:
    qty[(r['variable'], r['w'], r['item'], r['from'], r['to'])] += r['q']

# helper aggregations
prod_reg = defaultdict(Decimal)
prod_ot = defaultdict(Decimal)
setup = defaultdict(Decimal)
ship_pd = defaultdict(Decimal)
ship_dc = defaultdict(Decimal)
trans = defaultdict(Decimal)
inv = defaultdict(Decimal)
short = defaultdict(Decimal)
emerg = defaultdict(Decimal)
for (var,w,item,src,dst), q in qty.items():
    if var == 'produce_regular': prod_reg[(w,src,item)] += q
    elif var == 'produce_overtime': prod_ot[(w,src,item)] += q
    elif var == 'setup': setup[(w,src,item)] += q
    elif var == 'ship_plant_dc': ship_pd[(w,src,dst,item)] += q
    elif var == 'ship_dc_customer': ship_dc[(w,src,dst,item)] += q
    elif var == 'transfer_dc': trans[(w,src,dst,item)] += q
    elif var == 'inventory': inv[(w,src,item)] += q
    elif var == 'shortage': short[(w,src,item)] += q
    elif var == 'emergency_material': emerg[(w,dst,item)] += q

# feasibility and plant constraints
for w in weeks:
    for plant in plant_ids:
        reg_hours = Decimal('0')
        ot_hours = Decimal('0')
        setup_hours = Decimal('0')
        for product in product_ids:
            total_prod = prod_reg[(w,plant,product)] + prod_ot[(w,plant,product)]
            s = setup[(w,plant,product)]
            if total_prod > TOL and (plant, product) not in pp:
                add('time, location, readiness, setup, and non-overlap', (w, plant, product), 'Production only on feasible plant-product combinations', str(total_prod), '0 on infeasible combinations', 'Move production to a feasible plant-product pair.')
                continue
            if s > TOL and (plant, product) not in pp:
                add('time, location, readiness, setup, and non-overlap', (w, plant, product), 'Setup only on feasible plant-product combinations', str(s), '0 on infeasible combinations', 'Remove the infeasible setup row.')
                continue
            if (plant, product) in pp:
                rec = pp[(plant, product)]
                tph = Dq(rec['tons_per_hour'])
                reg_hours += prod_reg[(w,plant,product)] / tph
                ot_hours += prod_ot[(w,plant,product)] / tph
                setup_hours += s * Dq(rec['setup_hours'])
                max_weekly = Dq(rec['max_weekly_tons'])
                min_run = Dq(rec['min_run_tons'])
                if total_prod > TOL and s < Decimal('1') - TOL:
                    add('time, location, readiness, setup, and non-overlap', (w, plant, product), 'Positive production requires active setup', f'production={total_prod}, setup={s}', 'setup = 1 when production > 0', 'Add the missing setup row or reduce production to zero.')
                if s > Decimal('1') + TOL:
                    add('schema/nullability and key coverage', (w, plant, product), 'Setup is binary', str(s), '<= 1', 'Keep at most one active setup row per plant-product-week.')
                if total_prod > max_weekly + TOL:
                    add('time, location, readiness, setup, and non-overlap', (w, plant, product), 'Production must respect max weekly run size', str(total_prod), f'<= {max_weekly}', 'Reduce production on this run or split demand across other feasible plants/weeks.')
                if s > TOL and total_prod + TOL < min_run:
                    add('time, location, readiness, setup, and non-overlap', (w, plant, product), 'Active runs must meet the minimum run size', str(total_prod), f'>= {min_run}', 'Increase the run to the minimum or remove the setup and production rows.')
            shipped = sum(ship_pd[(w,plant,dc,product)] for dc in dc_ids)
            if shipped > total_prod + TOL:
                add('conservation and inventory', (w, plant, product), 'Plant outbound shipments must be supported by same-week production', str(shipped), f'<= {total_prod}', 'Cut plant shipments or raise same-week production at this plant-product.')
            if total_prod > shipped + TOL:
                add('conservation and inventory', (w, plant, product), 'Without a plant inventory state, produced product cannot disappear before shipping to a DC', f'production={total_prod}, shipments={shipped}', 'production should equal same-week plant shipments', 'Ship the full produced quantity to DCs or reduce production.')
        if reg_hours > Dq(plants[plant]['regular_hours']) + TOL:
            add('time, location, readiness, setup, and non-overlap', (w, plant), 'Regular production hours must stay within plant regular-hours capacity', str(reg_hours), f\"<= {plants[plant]['regular_hours']}\", 'Reduce regular production or move volume to other plants/weeks.')
        if ot_hours > Dq(plants[plant]['overtime_hours']) + TOL:
            add('time, location, readiness, setup, and non-overlap', (w, plant), 'Overtime production hours must stay within plant overtime capacity', str(ot_hours), f\"<= {plants[plant]['overtime_hours']}\", 'Reduce overtime production or shift volume.')
        if setup_hours > Dq(plants[plant]['weekly_setup_team_hours']) + TOL:
            add('time, location, readiness, setup, and non-overlap', (w, plant), 'Setup-team hours must stay within weekly setup capacity', str(setup_hours), f\"<= {plants[plant]['weekly_setup_team_hours']}\", 'Drop or move one of the setups in this plant-week.')

# material balances
for w in weeks:
    for plant in plant_ids:
        for material in material_ids:
            cons = Decimal('0')
            for product in product_ids:
                cons += bom.get((product, material), Decimal('0')) * (prod_reg[(w,plant,product)] + prod_ot[(w,plant,product)])
            regular, cap = mat_supply[(w, plant, material)]
            usable_regular = regular * material_discount
            e = emerg[(w, plant, material)]
            if e > cap + TOL:
                add('capacities and scenario derates', (w, plant, material), 'Emergency material purchases must respect the emergency cap', str(e), f'<= {cap}', 'Reduce emergency purchases or use a week/plant with remaining cap.')
            if cons > usable_regular + e + TOL:
                add('capacities and scenario derates', (w, plant, material), 'Material consumption must be covered by discounted regular supply plus emergency purchases', str(cons), f'<= {usable_regular + e}', 'Reduce production or add permitted emergency material to cover the deficit.')

# lane capacities and allowed arcs
for (w,plant,dc,product), q in ship_pd.items():
    if (plant,dc) not in plant_dc_lane:
        add('time, location, readiness, setup, and non-overlap', (w,plant,dc,product), 'Plant-to-DC shipments must use listed lanes', str(q), 'listed lane', 'Remove the forbidden lane or reroute through an allowed DC.')
for w in weeks:
    for plant, dc in plant_dc_lane:
        used = sum(ship_pd[(w,plant,dc,p)] for p in product_ids)
        if used > plant_dc_lane[(plant,dc)] + TOL:
            add('capacities and scenario derates', (w,plant,dc), 'Plant-to-DC lane throughput must stay within weekly lane capacity', str(used), f'<= {plant_dc_lane[(plant,dc)]}', 'Reduce or reroute plant shipments on this lane.')

for (w,dc,cust,product), q in ship_dc.items():
    if (dc,cust) not in dc_cust_lane:
        add('time, location, readiness, setup, and non-overlap', (w,dc,cust,product), 'DC-to-customer shipments must use listed lanes', str(q), 'listed lane', 'Remove the forbidden lane or reroute from an allowed DC.')
for w in weeks:
    for dc, cust in dc_cust_lane:
        used = sum(ship_dc[(w,dc,cust,p)] for p in product_ids)
        if used > dc_cust_lane[(dc,cust)] + TOL:
            add('capacities and scenario derates', (w,dc,cust), 'DC-to-customer lane throughput must stay within weekly lane capacity', str(used), f'<= {dc_cust_lane[(dc,cust)]}', 'Reduce shipments on this lane or split volume across other allowed lanes.')

for (w,dc1,dc2,product), q in trans.items():
    if (dc1,dc2) not in dc_transfer_lane:
        add('time, location, readiness, setup, and non-overlap', (w,dc1,dc2,product), 'DC transfers must use listed lanes', str(q), 'listed lane', 'Remove or reroute the transfer.')
for w in weeks:
    for dc1, dc2 in dc_transfer_lane:
        used = sum(trans[(w,dc1,dc2,p)] for p in product_ids)
        if used > dc_transfer_lane[(dc1,dc2)] + TOL:
            add('capacities and scenario derates', (w,dc1,dc2), 'DC transfer throughput must stay within weekly lane capacity', str(used), f'<= {dc_transfer_lane[(dc1,dc2)]}', 'Reduce or reroute the transfer volume.')

# demand balance and service
for key, dem in demand.items():
    w, cust, product = key
    shipped = sum(ship_dc[(w,dc,cust,product)] for dc in dc_ids)
    shortage = short[(w,cust,product)]
    if abs((shipped + shortage) - dem) > TOL:
        add('schema/nullability and key coverage', key, 'Each demand tuple must be fully accounted by shipments plus shortage', str(shipped + shortage), f'= {dem}', 'Add the missing shortage/shipment quantity or remove the excess volume.')
    min_rate = Dq(customers[cust]['min_service_rate'])
    if shipped + TOL < dem * min_rate:
        add('capacities and scenario derates', key, 'Customer minimum service requirement must be met', str(shipped), f'>= {dem * min_rate}', 'Increase deliveries or reduce shortage on this customer-week-product tuple.')

# unexpected shortage rows for nonexistent demand keys
for (w,cust,product), q in short.items():
    if (w,cust,product) not in demand:
        add('schema/nullability and key coverage', (w,cust,product), 'Shortage rows are only valid for demand tuples present in demand.csv', str(q), 'existing demand key', 'Remove the orphan shortage row.')

# inventory balance, nonnegativity, reserves, capacity
customer_region_demand = defaultdict(Decimal)
for (w,cust,product), dem in demand.items():
    region = customers[cust]['region']
    customer_region_demand[(w,region,product)] += dem

for product in product_ids:
    for dc in dc_ids:
        prev = initial_inventory[(dc,product)]
        region = dcs[dc]['region']
        for w in weeks:
            inbound = sum(ship_pd[(w,plant,dc,product)] for plant in plant_ids) + sum(trans[(w,src,dc,product)] for src in dc_ids if src "'!= dc)
            outbound = sum(ship_dc[(w,dc,cust,product)] for cust in customer_ids) + sum(trans[(w,dc,dst,product)] for dst in dc_ids if dst != dc)
            end = inv[(w,dc,product)]
            implied = prev + inbound - outbound
            if abs(end - implied) > TOL:
                add('"'conservation and inventory', (w,dc,product), 'DC inventory must equal prior inventory plus inbound minus outbound', str(end), f'= {implied}', 'Fix the inventory row or the associated inbound/outbound shipment rows.')
            if end < -TOL:
                add('conservation and inventory', (w,dc,product), 'End-of-week inventory must be nonnegative', str(end), '>= 0', 'Raise inbound volume, lower outbound volume, or increase beginning inventory.')
            next_dem = customer_region_demand.get((w+1, region, product), Decimal('0'))
            required = safety[(dc,product)] + reserve_mult * next_dem
            if end + TOL < required:
                add('reserves/ramps', (w,dc,product), 'DC ending inventory must cover safety stock plus next-week regional reserve', str(end), f'>= {required}', 'Hold more stock at this DC or shift inbound volume earlier.')
            prev = end

for w in weeks:
    for dc in dc_ids:
        total = sum(inv[(w,dc,p)] for p in product_ids)
        cap = Dq(dcs[dc]['capacity_tons'])
        if total > cap + TOL:
            add('capacities and scenario derates', (w,dc), 'Warehouse freezer inventory must stay within DC capacity', str(total), f'<= {cap}', 'Reduce stock at this DC or transfer volume to another warehouse.')

# objective recomputation
prod_cost = Decimal('0'); setup_cost = Decimal('0'); ship_pd_cost = Decimal('0'); ship_dc_cost = Decimal('0'); trans_cost = Decimal('0'); hold_cost = Decimal('0'); short_cost = Decimal('0'); em_cost = Decimal('0')
plant_dc_cost_map = {(r['plant_id'], r['dc_id']): Dq(r['cost_per_ton']) for r in read_csv(D/'plant_to_dc_lanes.csv')}
dc_cust_cost_map = {(r['dc_id'], r['customer_id']): Dq(r['cost_per_ton']) for r in read_csv(D/'dc_to_customer_lanes.csv')}
dc_transfer_cost_map = {(r['from_dc'], r['to_dc']): Dq(r['cost_per_ton']) for r in read_csv(D/'dc_transfer_lanes.csv')}
for (w,plant,product), q in prod_reg.items():
    if q:
        prod_cost += q * Dq(pp[(plant,product)]['regular_cost_per_ton'])
for (w,plant,product), q in prod_ot.items():
    if q:
        prod_cost += q * Dq(pp[(plant,product)]['overtime_cost_per_ton'])
for (w,plant,product), q in setup.items():
    if q:
        setup_cost += q * Dq(pp[(plant,product)]['setup_cost'])
for (w,plant,dc,product), q in ship_pd.items():
    ship_pd_cost += q * plant_dc_cost_map[(plant,dc)]
for (w,dc,cust,product), q in ship_dc.items():
    ship_dc_cost += q * (dc_cust_cost_map[(dc,cust)] + Dq(dcs[dc]['handling_cost_per_ton']))
for (w,dc1,dc2,product), q in trans.items():
    trans_cost += q * dc_transfer_cost_map[(dc1,dc2)]
for (w,dc,product), q in inv.items():
